// delete-account — single-file build of supabase/functions/delete-account for pasting into the Supabase dashboard editor. Generated by scripts/build-dashboard-functions.sh; do not edit by hand.

// supabase/functions/_shared/http.ts
import { createClient } from "npm:@supabase/supabase-js@2";
var corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS"
};
function json(body, status = 200) {
  return new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, "Content-Type": "application/json" } });
}
function errorResponse(err) {
  const message = err instanceof Error ? err.message : String(err?.message ?? err);
  const status = /forbidden|not_authenticated/.test(message) ? 403 : /not_found/.test(message) ? 404 : /confirmation_required|already_running|invalid_transition|registration_still_open|rerun_after_reveal|event_paused|primary_round_required/.test(message) ? 409 : /invalid_input/.test(message) ? 400 : 500;
  return json({ error: message }, status);
}
var url = () => Deno.env.get("SUPABASE_URL");
function serviceClient() {
  return createClient(url(), Deno.env.get("SUPABASE_SERVICE_ROLE_KEY"), { auth: { persistSession: false } });
}
function userClient(req) {
  return createClient(url(), Deno.env.get("SUPABASE_ANON_KEY"), {
    auth: { persistSession: false },
    global: { headers: { Authorization: req.headers.get("Authorization") ?? "" } }
  });
}
async function requireUser(req) {
  const client = userClient(req);
  const { data, error } = await client.auth.getUser();
  if (error || !data.user) throw new Error("not_authenticated");
  return { client, user: data.user };
}
function rpcOf(client) {
  return async (fn, args) => {
    const { data, error } = await client.rpc(fn, args);
    if (error) throw new Error(error.message);
    return data;
  };
}
function handleOptions(req) {
  return req.method === "OPTIONS" ? new Response("ok", { headers: corsHeaders }) : null;
}

// supabase/functions/delete-account/index.ts
Deno.serve(async (req) => {
  const pre = handleOptions(req);
  if (pre) return pre;
  try {
    const body = await req.json().catch(() => ({}));
    if (body.confirm !== "DELETE") return json({ error: "confirmation_required" }, 409);
    const { user } = await requireUser(req);
    const svc = serviceClient();
    await rpcOf(svc)("service_prepare_account_deletion", { p_user: user.id });
    for (const bucket of ["resumes", "avatars"]) {
      const { data: files } = await svc.storage.from(bucket).list(user.id, { limit: 1e3 });
      if (files?.length) await svc.storage.from(bucket).remove(files.map((f) => `${user.id}/${f.name}`));
    }
    const { error } = await svc.auth.admin.deleteUser(user.id);
    if (error) throw error;
    return json({ deleted: true });
  } catch (err) {
    return errorResponse(err);
  }
});
